// registry + decision + server timestamp (registry copied from 10_tag_registry.json)
const READERS = { "LAB-A-READER-01": "LAB-A", "LAB-B-READER-01": "LAB-B", "STORE-READER-01": "STORE" };
const TAGS = {
    "A1B2C3D4": { entity_id: "USER-001", locations: ["LAB-A"], status: "ACTIVE" },
    "99AABBCC": { entity_id: "USER-002", locations: ["LAB-A", "LAB-B"], status: "ACTIVE" },
    "55667788": { entity_id: "USER-003", locations: ["LAB-A"], status: "INACTIVE" },
    "11223344": { entity_id: "ASSET-007", locations: ["*"], status: "ACTIVE" },
};

const scan = msg.payload;
if (typeof scan !== "object" || scan === null || typeof scan.tag_uid !== "string" || !(scan.reader_id in READERS)) {
    node.warn("invalid scan message");
    return null;
}

const uid = scan.tag_uid.replace(/[\s:]/g, "").toUpperCase();
const location = READERS[scan.reader_id];
const eventType = scan.event_type || "ACCESS_ATTEMPT";
const tag = TAGS[uid];

let decision = "ACCESS_GRANTED", reason = "authorized";
if (!tag) { decision = "ACCESS_DENIED"; reason = "tag not registered"; }
else if (tag.status !== "ACTIVE") { decision = "ACCESS_DENIED"; reason = "tag inactive"; }
else if (eventType === "ASSET_SCAN") { decision = "ASSET_RECORDED"; reason = "asset seen at " + location; }
else if (!tag.locations.includes(location)) { decision = "ACCESS_DENIED"; reason = "no permission for " + location; }

const event = {
    timestamp: new Date().toISOString(),
    reader_id: scan.reader_id,
    location: location,
    tag_uid: uid,
    entity_id: tag ? tag.entity_id : "UNKNOWN",
    event_type: eventType,
    decision: decision,
    reason: reason,
};

let recent = flow.get("recent") || [];
recent.unshift(event);
recent = recent.slice(0, 20);
flow.set("recent", recent);

let counts = flow.get("counts") || { total: 0, granted: 0, denied: 0, asset: 0 };
counts.total++;
if (decision === "ACCESS_GRANTED") counts.granted++;
else if (decision === "ACCESS_DENIED") counts.denied++;
else counts.asset++;
flow.set("counts", counts);

// outputs: event, recent events table, counters
return [
    { payload: event },
    { payload: recent },
    { payload: `Total ${counts.total} | Granted ${counts.granted} | Denied ${counts.denied} | Asset ${counts.asset}` },
];
